import { chmodSync, copyFileSync, cpSync, mkdirSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { validateSkillDirectory } from "../../../scripts/lib/validate-skill.mjs";

const pkgRoot = join(dirname(fileURLToPath(import.meta.url)), "..");
const repoRoot = join(pkgRoot, "..", "..");
const canonicalSkillDir = join(repoRoot, "crates", "bsk-cli", "skill");

const { name, description, content, files } = validateSkillDirectory(canonicalSkillDir, {
  maxEntryBytes: 2_000,
});

const destSkillDir = join(pkgRoot, "skill");
rmSync(destSkillDir, { recursive: true, force: true });
cpSync(canonicalSkillDir, destSkillDir, { recursive: true });

for (const asset of ["install.sh", "install.ps1", "AGENT_INSTALL.md", "LICENSE"]) {
  copyFileSync(join(repoRoot, asset), join(pkgRoot, asset));
}
if (process.platform !== "win32") {
  chmodSync(join(pkgRoot, "install.sh"), 0o755);
  chmodSync(join(pkgRoot, "bin", "install-bsk.mjs"), 0o755);
}

mkdirSync(join(pkgRoot, "src"), { recursive: true });
const banner =
  "// GENERATED by scripts/build-bundle.mjs — do not edit.\n" +
  "// Source: crates/bsk-cli/skill/SKILL.md; references load on demand from resourceBase.\n";
writeFileSync(
  join(pkgRoot, "src", "skill-content.generated.mts"),
  `${banner}export const BSK_SKILL_NAME = ${JSON.stringify(name)};\n` +
    `export const BSK_SKILL_DESCRIPTION = ${JSON.stringify(description)};\n` +
    `export const BSK_SKILL_MARKDOWN = ${JSON.stringify(content)};\n`,
);

console.log(
  `dsh-plugin bundle synced (${files.size} skill files, ${Buffer.byteLength(content)} body bytes)`,
);
